import {DatabaseSync} from 'node:sqlite';
const db=new DatabaseSync('codegraph.db',{readOnly:true});
function callers(name,file){
  const tgt=db.prepare(`SELECT id,qualified_name FROM nodes WHERE name=? AND file_path=?`).all(name,file);
  for(const t of tgt){
    const srcs=db.prepare(`SELECT DISTINCT n.name sname, n.file_path fp FROM edges e JOIN nodes n ON n.id=e.source WHERE e.kind='calls' AND e.target=? ORDER BY fp`).all(t.id);
    console.log(`\n== ${t.qualified_name} (id ${t.id}) — ${srcs.length} distinct callers`);
    const byfile={};
    for(const s of srcs){byfile[s.fp]=(byfile[s.fp]||0)+1;}
    for(const [fp,c] of Object.entries(byfile).sort((a,b)=>b[1]-a[1]).slice(0,15))
      console.log(`   ${c}\t${fp}`);
  }
}
callers('Len','internal/version/version.go');
callers('Next','internal/scheduler/parser.go');
EOF
node --no-warnings /tmp/q4.mjs

